valid.code:
const variable = 1;
class Class {}
enum Enum {}
function Func() {}
namespace ValueNS {
  export const x = 1;
}

export { variable, Class, Enum, Func, ValueNS };

type Alias = 1;
interface IFace {}
namespace TypeNS {
  export type x = 1;
}

export type { Alias, IFace, TypeNS };

namespace NonTypeNS {
  export const x = 1;
}

export { NonTypeNS };

import * as Foo from './consistent-type-exports';
type Foo = 1;
export { Foo }

import { Type1 } from './consistent-type-exports';
const Type1 = 1;
export { Type1 };

invalid.code:
export {
  Type2 as Foo,
  value1 as BScope,
  value2 as CScope,
} from './consistent-type-exports';

output:
import { value2, Type2 } from './consistent-type-exports';
export type { Type2 };
export { value2 };

